// Calculate inclusive Monday-Friday working days
const payload = $input.item.json.body || $input.item.json;
const startDateStr = payload.start_date;
const endDateStr = payload.end_date;

if (!startDateStr || !endDateStr) {
  throw new Error('start_date and end_date are required for working day calculation.');
}

const start = new Date(startDateStr + 'T00:00:00Z');
const end = new Date(endDateStr + 'T00:00:00Z');

if (isNaN(start.getTime()) || isNaN(end.getTime())) {
  throw new Error('Invalid date format for working day calculation. Expected YYYY-MM-DD.');
}

if (end < start) {
  throw new Error('end_date cannot be earlier than start_date.');
}

let workingDays = 0;
const current = new Date(start);

while (current <= end) {
  const dayOfWeek = current.getUTCDay(); // 0 is Sunday, 6 is Saturday
  if (dayOfWeek !== 0 && dayOfWeek !== 6) {
    workingDays++;
  }
  current.setUTCDate(current.getUTCDate() + 1);
}

return {
  json: {
    ...payload,
    net_working_days: workingDays,
    calculated_at: new Date().toISOString()
  }
};
